import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"Tagged Values","description":"","frontmatter":{"title":"Tagged Values","type":"adr","date":"2026-09-01T00:00:00.000Z","status":"accepted","status_note":"Accepted — tagged values; forgery is impossible."},"headers":[],"relativePath":"handl/project/adrs/0055-branded-values.md","filePath":"vendored/handl/project/adrs/0055-branded-values.md"}`),a={name:`handl/project/adrs/0055-branded-values.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0055-tagged-values" tabindex="-1">ADR-0055: Tagged Values <a class="header-anchor" href="#adr-0055-tagged-values" aria-label="Permalink to “ADR-0055: Tagged Values”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong>Tag registries</strong> define the legal tags per host; a tag is registered once and carries its rules.</li><li><strong><code>tag</code> / <code>match_tag</code> / <code>tag_registry</code> are host capabilities</strong>, not syntax.</li><li><strong>Representation</strong>: a tagged value is a <code>serde_json::Value</code> carrying its tag and payload; no new value kind.</li><li><strong>Two equality flavors, one primitive</strong>: structural equality and tag-identity equality share one comparison primitive.</li><li><strong>Forgery is impossible</strong> — a tag can only be minted through the registered capability.</li><li><strong>Sugar</strong>: <code>type</code> (and future <code>unit</code>) declares tags; the primitive is the capability.</li><li><strong>Untagged values are unchanged</strong>; tagging is additive.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>Types and branded values were Rust enums, so a tag could be forged by constructing the variant and new tags meant engine changes. Registry-minted tagged values make tags unforgeable and additive.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>A new value kind</strong> — tags ride on <code>serde_json::Value</code>.</li><li><strong>Constructor-based tags</strong> — only the registry mints them.</li><li><strong>One equality for everything</strong> — two flavors share one primitive.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Tags are data; forging requires the capability, not the constructor.</li><li>Equality is explicit: structural vs tag identity.</li><li>Untagged code is unaffected.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kernel/</code> — tag registry and minting capability.</li><li><code>plugin-lib-tag/</code> — the host primitive.</li><li>Typechecker tests for forgery/equality.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Registries, capabilities, representation, equality and the sugar: +<a href="./../design/0055-branded-values.html"><code>design/0055-branded-values.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};